style.css:
/* bunny cloud — Roblox */

:root {
  --my-pink: #f3dce4;
  --my-blush: #e9c5d1;
  --my-cream: #fff8f5;
  --my-brown: #947b78;
}

/* overall page */
html,
body {
  background-color: var(--my-cream) !important;
  color: var(--my-brown) !important;
}

/* Roblox navigation */
header,
nav {
  background-color: var(--my-pink) !important;
  color: var(--my-brown) !important;
}

/* links */
a {
  color: var(--my-brown) !important;
}

/* buttons */
button,
[role="button"] {
  border-radius: 12px !important;
}

/* text boxes */
input,
textarea {
  background-color: #fffaf8 !important;
  border: 1px solid var(--my-blush) !important;
  border-radius: 10px !important;
}

/* selected text */
::selection {
  background: var(--my-blush) !important;
}
